package com.finance.repository; import com.finance.model.RecurringTransaction; import org.springframework.data.mongodb.repository.MongoRepository; import java.util.List; import java.util.Optional; public interface RecurringRepository extends MongoRepository<RecurringTransaction,String>{ List<RecurringTransaction> findByUserId(String userId); List<RecurringTransaction> findByActiveTrue(); Optional<RecurringTransaction> findByIdAndUserId(String id,String userId); }
